def oranges_rotting_brute(grid):
    rows, cols = len(grid), len(grid[0])
    minutes = 0
    while True:
        to_rot = []
        for r in range(rows):                                  # rescan the ENTIRE grid every minute
            for c in range(cols):
                if grid[r][c] == 1:
                    for dr, dc in [(1,0),(-1,0),(0,1),(0,-1)]:
                        nr, nc = r+dr, c+dc
                        if 0<=nr<rows and 0<=nc<cols and grid[nr][nc]==2:
                            to_rot.append((r, c))
                            break
        if not to_rot:
            break
        for r, c in to_rot:
            grid[r][c] = 2
        minutes += 1
    if any(1 in row for row in grid):
        return -1
    return minutes

